import{_ as l,b as s,c as a,f as e}from"./chunks/framework.86O3EbG5.js";const f=JSON.parse('{"title":"女性主义图书增加意味着什么","description":"","frontmatter":{"title":"女性主义图书增加意味着什么","author":"oasis","date":"2026-05-11T00:00:00.000Z","tags":["Date Log"]},"headers":[],"relativePath":"articles/self/2.md","filePath":"articles/self/2.md"}'),n={name:"articles/self/2.md"};function r(i,t,o,p,c,d){return s(),a("div",null,[...t[0]||(t[0]=[e("p",null,"最近浏览微信读书，在“神作”分类中，女性主义的书籍有一些，像《第二性》《看不见的女性》以及一些日本作家的关于女性的著作。",-1),e("p",null,"首先，我需要验证这是否源于我的阅读偏好——因为我关注了女性主义，所以才发现相关书籍变多。为此我分析了豆瓣读书年度书单。",-1),e("p",null,"数据表明，女性主义相关书籍入选趋势在增加。然而，女性主义书籍的增多到底是否意味着女性主义的启蒙？我的回答是否定的：女性主义概念正在被资本消费，而非真正对女性进行女性主义启蒙。",-1),e("p",null,"“商品女性主义”（commodity feminism）由美国文化评论家Andi Zeisler在其著作《We Were Feminists Once》中系统阐述。她指出，资本主义媒介体系善于将女性主义“从一个挑战权力结构的政治运动，转变为一种个人主义的、以消费为中心的身份表达”。在这一转换中，“独立”“强大”“自由”不再是需要制度保障的社会权利，而是通过购买某支口红、某本书、某门课程即可瞬时获得的“情感代餐”。",-1),e("p",null,"中国学者在此基础上进一步提出“商品女性主义：商品逻辑对女性主义的异化”（2022），指出资本逻辑对女性主义的收编遵循三步路径：去政治化（剥离平权斗争的历史与制度诉求）、个体化（将结构性问题转化为个人选择与情感管理）、符号化（将特定商品与“女性力量”标签绑定）。这正是理解当下“她经济”热潮的关键分析工具。",-1),e("p",null,"出版市场的繁荣只是“商品女性主义”的一个切片。在社交媒体与广告营销中，这种收编更为赤裸。典型如“三八女神节”的造节运动——原本纪念妇女争取劳动权益的节日，被重构为“宠爱自己”“奖励自己”的购物狂欢。广告文案反复调用“独立女性应该拥有一支……”的话术，将“独立”与特定消费品强制捆绑。学者将其称之为“女性焦虑的生产”（2023）：媒介先制造“你不够好”“你需要更强大”的焦虑，再兜售以“赋权”为包装的解决方案——实质上从未触及同工不同酬、家务分配不公、职场晋升“玻璃天花板”等结构性问题。",-1),e("p",null,"郑丹丹（2023）在《当代中国女性主义思潮的演进、效应与引领》一文中提醒，多股力量正在争夺女性主义话语的主导权，其中消费主义的收编力量最为隐蔽也最具侵蚀性。一旦女性主义被简化为“买买买”与“做更好的自己”，它就丧失了挑战父权制与资本共谋的锋芒，变成资本主义再生产自身的润滑剂。",-1)])])}const u=l(n,[["render",r]]);export{f as __pageData,u as default};
